function addCart(id,redraw=true){if(saleInFlight)return;if(!can(role,'sell'))return toast(t('permission'));const p=products().find(p=>p.id===id);const line=cart.find(l=>l.productId===id);const available=p?p.stock-(line?.quantity||0):0;const increment=p&&['m','m²','kg','g','l','ml'].includes(p.unit)?Math.min(1,available):1;if(!p||p.active===false||available<=0||increment>available)return toast(t('stockError'));if(line)line.quantity=Math.round((line.quantity+increment)*1000)/1000;else cart.push({productId:id,quantity:increment});if(redraw)render();return true;}
