function receipt(s){if(!s)return;modal(`<div class="receipt"><img src="/icon.svg" alt="Pronto POS"><h2>${esc(tenant().name)}</h2><p>${t('receipt')} · #${esc(s.id.slice(0,8).toUpperCase())}</p>${s.customerId?`<p>${lang==='pt'?'Cliente':'Customer'}: ${esc((state.customers||[]).find(c=>c.id===s.customerId)?.name||'—')}</p>`:''}${s.lines.map(l=>`<div class="list-row"><div>${esc(l.name)}<small>${l.quantity} ${esc(l.unit)} × ${money(l.price)}</small></div><strong>${money(l.total)}</strong></div>`).join('')}<div class="receipt-payments">${s.discount?`<p>Subtotal: ${money(s.subtotal)} · ${lang==='pt'?'Desconto':'Discount'}: ${money(s.discount)}</p>`:''}${(s.payments||[{method:s.method,amount:s.total}]).map(p=>`<div><span>${t(p.method)}</span><strong>${money(p.amount)}</strong></div>`).join('')}</div><div class="total">${t('total')}<strong>${money(s.total)}</strong></div><p>${s.method==='mixed'?(lang==='pt'?'Pagamento repartido':'Split payment'):t(s.method)} · ${t('received')}: ${money(s.received)}<br>${t('change')}: ${money(s.change)}</p><small>${t('localOnly')}</small><button id="share-receipt" class="primary full">${t('share')}</button><button id="print-receipt" class="secondary full">${t('print')}</button></div>`);click('print-receipt',()=>window.print());click('share-receipt',async()=>{const text=[tenant().name,t('receipt'),...s.lines.map(l=>`${l.name}: ${l.quantity} ${l.unit} — ${money(l.total)}`),`${t('total')}: ${money(s.total)}`,t('localOnly')].join('\n');try{if(navigator.share)await navigator.share({title:'Pronto POS',text});else{await navigator.clipboard.writeText(text);toast(lang==='pt'?'Comprovativo copiado.':'Receipt copied.');}}catch(error){if(error.name!=='AbortError')toast(t('saveError'));}});}
