function paymentHelp(){if(!cart.length)return '';if(method==='mixed')return lang==='pt'?'A soma dos meios deve coincidir com o total.':'Payment amounts must match the total.';if(method!=='cash')return lang==='pt'?'Confirme o recebimento antes de concluir.':'Confirm payment before finishing.';if(!received.trim())return lang==='pt'?'Introduza o valor entregue pelo cliente.':'Enter the cash tendered.';const left=dueTotal()-cents(received);return left>0?`${lang==='pt'?'Faltam':'Remaining'} ${money(left)}`:(lang==='pt'?'Confira o troco.':'Check the change.');}
