function draftKey(){return `pronto-draft:${tenantId}:${role}`;}
function saveDraft(){if(isRemote||!state||!can(role,'sell'))return;try{sessionStorage.setItem(draftKey(),JSON.stringify({cart,method,received,selectedCustomerId}));}catch{/* Sale entry remains available when browser storage is restricted. */}}
function restoreDraft(){cart=[];received='';selectedCustomerId='';if(isRemote||!can(role,'sell'))return;try{const draft=JSON.parse(sessionStorage.getItem(draftKey())||'null');if(!draft)return;cart=(draft.cart||[]).filter(l=>products().some(p=>p.id===l.productId&&p.active!==false)&&Number.isFinite(l.quantity)&&l.quantity>0);method=['cash','mpesa','emola','transfer','mixed'].includes(draft.method)?draft.method:'cash';received=String(draft.received||'');selectedCustomerId=(state.customers||[]).some(c=>c.id===draft.selectedCustomerId&&c.tenantId===tenantId)?draft.selectedCustomerId:'';}catch{/* Ignore damaged drafts; confirmed sales stay in IndexedDB. */}}

