function cashError(error){const key=error.message;return lang==='pt'?({cash_insufficient:'O caixa não tem dinheiro suficiente para esta retirada.',cash_difference_note:'Explique as diferenças na observação do fecho.',cash_not_open:'Este caixa já não está aberto.',cash_already_open:'Já existe um caixa aberto neste dispositivo.',cash_amount:'Indique um valor válido, com até duas casas decimais.'}[key]||'Não foi possível guardar o movimento.') : ({cash_insufficient:'Insufficient cash for this withdrawal.',cash_difference_note:'Explain closing differences in the note.',cash_not_open:'This register is no longer open.',cash_already_open:'A register is already open on this device.',cash_amount:'Enter a valid amount with at most two decimal places.'}[key]||'Unable to save this movement.');}
function parseCash(value){const number=Number(value);if(!String(value).trim()||!Number.isFinite(number)||number<0||Math.abs(number*100-Math.round(number*100))>.00001)throw Error('cash_amount');return Math.round(number*100);}
function bindCash(){click('cash-open',()=>cashForm('open'));click('cash-in',()=>cashForm('in'));click('cash-out',()=>cashForm('out'));click('cash-close',cashCloseForm);document.querySelectorAll('[data-cash-review]').forEach(button=>button.onclick=()=>{const session=(state.cashSessions||[]).find(s=>s.id===button.dataset.cashReview&&s.tenantId===tenantId);if(session)modal(reconciliation({state,session,lang,money,closed:true}));});}
function cashForm(type){if(!can(role,'sell'))return;const l=cashLabels(lang);const d=modal(`<h2>${type==='open'?l.open:l[type]}</h2><form id="cash-form"><label>${type==='open'?l.opening:l.amount}<input name="amount" type="number" min="${type==='open'?'0':'0.01'}" step="0.01" inputmode="decimal" required></label>${type==='open'?'':`<label>${l.reason}<input name="reason" maxlength="200" required></label>`}<button class="primary full">${l.save}</button></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),button=e.target.querySelector('button');try{const amount=parseCash(f.get('amount'));button.disabled=true;state=isRemote?await remoteAction(type==='open'?'cash/open':'cash/move',type==='open'?{opening:amount}:{type,amount,reason:f.get('reason')}):await update(current=>type==='open'?openCash(current,cashContext(),amount):moveCash(current,cashContext(),{type,amount,reason:f.get('reason')}));d.close();render();toast(lang==='pt'?'Caixa actualizado.':'Register updated.');}catch(error){button.disabled=false;toast(cashError(error));}};}
function cashCloseForm(){const session=activeCash(state,cashContext());if(!session)return;const d=modal(`<form id="cash-close-form">${reconciliation({state,session,lang,money})}</form>`);const form=d.querySelector('form');form.querySelectorAll('[data-expected]').forEach(input=>input.oninput=()=>{const amount=cents(input.value);form.querySelector(`[data-difference="${input.name}"]`).textContent=`${cashLabels(lang).difference}: ${Number.isSafeInteger(amount)?money(amount-Number(input.dataset.expected)):'—'}`;});form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form),button=form.querySelector('button');try{const counted=Object.fromEntries(paymentMethods.map(method=>[method,parseCash(f.get(method))]));button.disabled=true;state=isRemote?await remoteAction('cash/close',{counted,note:f.get('note')}):await update(current=>closeCash(current,cashContext(),counted,f.get('note')));d.close();render();toast(lang==='pt'?'Caixa fechado.':'Register closed.');}catch(error){button.disabled=false;toast(cashError(error));}};}


function splitFields(){const en=lang==='en';return `<div class="split-payments"><p>${en?'Enter amount per payment method.':'Indique o montante por meio de pagamento.'}</p><div class="split-grid">${paymentMethods.map(m=>`<label>${t(m)} (MT)<input data-split="${m}" type="number" min="0" step="0.01" inputmode="decimal" value="${esc(mixed[m])}"></label>`).join('')}</div>${cashNeeded()>0?`<label>${t('received')} (MT)<input id="received" type="number" min="0" step="0.01" inputmode="decimal" value="${esc(received)}"></label><div class="change">${t('change')} <strong id="change">${money(Math.max(0,(cents(received)||0)-cashNeeded()))}</strong></div>`:''}</div>`;}
function holdSale(){if(!cart.length)return;holds.push({tenantId,selectedCustomerId,cart:cart.map(x=>({...x})),method,received,discountText,mixed:{...mixed}});cart=[];received='';selectedCustomerId='';discountText='0';mixed={cash:'',mpesa:'',emola:'',transfer:''};pendingSaleId='';pendingSaleFingerprint='';render();toast(lang==='pt'?'Venda suspensa nesta aba.':'Sale held in this tab.');}
function resumeSale(){const i=holds.findLastIndex(x=>x.tenantId===tenantId);if(i<0)return;if(cart.length){toast(lang==='pt'?'Suspenda ou limpe a venda actual.':'Hold or clear the current sale.');return;}const s=holds.splice(i,1)[0];cart=s.cart.filter(x=>products().some(p=>p.id===x.productId&&p.active!==false&&p.stock>=x.quantity));method=s.method;received=s.received;selectedCustomerId=(state.customers||[]).some(c=>c.id===s.selectedCustomerId&&c.tenantId===tenantId)?s.selectedCustomerId:'';discountText=s.discountText;mixed=s.mixed;pendingSaleId='';pendingSaleFingerprint='';render();}
function refundForm(id){if(!can(role,'refund'))return toast(t('permission'));const s=sales().find(x=>x.id===id&&!x.refundId);if(!s)return;if(!activeCash(state,cashContext())){toast(lang==='pt'?'Abra um caixa antes de devolver.':'Open a register before a return.');return;}const en=lang==='en',electronic=(s.payments||[{method:s.method}]).some(p=>p.method!=='cash'),d=modal(`<h2>${en?'Full return':'Devolução integral'} · #${esc(s.id.slice(0,8))}</h2><p>${en?'All items will be restored to stock.':'Todos os artigos serão devolvidos ao stock.'}</p><strong>${money(s.total)}</strong><div class="receipt-payments">${(s.payments||[{method:s.method,amount:s.total}]).map(p=>`<div><span>${t(p.method)}</span><strong>${money(p.amount)}</strong></div>`).join('')}</div><form id="refund-form"><label>${en?'Reason':'Motivo'}<textarea name="reason" rows="3" maxlength="300" required></textarea></label><label class="confirm-refund"><input type="checkbox" name="confirmed" required> ${electronic?(en?'I confirm that I have manually repaid the customer. No electronic refund will be sent by this app.':'Confirmo que reembolsei manualmente o cliente. O sistema não envia reembolsos electrónicos.'):(en?'I confirm the money was returned to the customer.':'Confirmo que o dinheiro foi devolvido ao cliente.')}</label><button class="primary full">${en?'Record return':'Registar devolução'}</button></form>`);d.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),reason=String(f.get('reason')).trim(),btn=e.target.querySelector('button');if(!reason||f.get('confirmed')!=='on')return;btn.disabled=true;const refund={id:crypto.randomUUID(),saleId:id,reason,manualConfirmed:true};try{state=isRemote?await remoteAction('refunds',refund):await update(current=>refundSale(current,cashContext(),refund));d.close();render();toast(en?'Return recorded.':'Devolução registada.');}catch(error){btn.disabled=false;toast(error.message==='cash_insufficient'?(en?'Insufficient cash for this refund.':'Dinheiro insuficiente no caixa.'):t('saveError'));}};}

function bindSaleHistory(){
 const output=document.getElementById('sale-history-results');
 if(!output)return;
 const redraw=()=>{
  const filtered=filterSaleHistory(sales(),saleFilters);
  output.innerHTML=saleList(filtered);
  document.getElementById('sale-history-count').textContent=`${filtered.length} ${lang==='pt'?'vendas':'sales'}`;
  output.querySelectorAll('[data-receipt]').forEach(b=>b.onclick=()=>receipt(sales().find(s=>s.id===b.dataset.receipt)));
 };
 for(const [id,key] of [['sale-history-search','search'],['sale-history-method','method'],['sale-history-status','status'],['sale-history-from','from'],['sale-history-to','to']]){
  const node=document.getElementById(id);
  if(!node)continue;
  node[id==='sale-history-search'?'oninput':'onchange']=()=>{
    saleFilters[key]=node.value;
    if(saleFilters.from&&saleFilters.to&&saleFilters.from>saleFilters.to){
     if(key==='from'){saleFilters.to='';document.getElementById('sale-history-to').value='';}
     else if(key==='to'){saleFilters.from='';document.getElementById('sale-history-from').value='';}
    }
    redraw();
  };
 }
 click('sale-history-reset',()=>{saleFilters={search:'',method:'all',status:'all',from:'',to:''};render();});
}
